}

static void log_reply(CLIENT *client, struct nbd_reply *prply) {
	if (client->transactionlogfd != -1) {
		lock_logsem(client);
		writeit(client->transactionlogfd, prply, sizeof(*prply));
		unlock_logsem(client);
