void rclist_unlink(struct rclist *l, struct reqcontext *p)
{
	if (p && l) {
		struct reqcontext *prev = p->prev;
		struct reqcontext *next = p->next;

		/* Fix link to previous */
		if (prev)
			prev->next = next;
		else
			l->head = next;

		if (next)
			next->prev = prev;
		else
			l->tail = prev;

		p->prev = NULL;
		p->next = NULL;
		l->numitems--;
	}
}

